func init() {
	languages := []string{"zh-Hans", "zh-Hant", "ja", "es", "fr"}
	for english, localized := range continuePreflightTranslations {
		if len(localized) != len(languages) {
			panic("invalid Continue preflight translation row for " + english)
		}
		for index, language := range languages {
			Translations[language][english] = localized[index]
		}
	}
}
